package com.logatron.investigation.web;
import com.logatron.investigation.domain.InvestigationModels.IdentifierType;import com.logatron.investigation.persistence.InvestigationEntity;import java.time.Instant;import java.util.*;
public final class InvestigationDtos {private InvestigationDtos(){}public record CreateInvestigationRequest(String question,UUID projectId,UUID environmentId,Instant from,Instant to,IdentifierType identifierType,String identifierValue){}public record StoredInvestigation(UUID id,UUID projectId,UUID environmentId,Instant createdAt,Instant from,Instant to,String queryKind,String status,List<String> evidenceReferences,Map<String,String> qualityMetadata,String aiProvider,String aiModel,String aiOutcome,Long aiLatencyMs){public static StoredInvestigation from(InvestigationEntity e){return new StoredInvestigation(e.getId(),e.getProjectId(),e.getEnvironmentId(),e.getCreatedAt(),e.getFromTime(),e.getToTime(),e.getQueryKind(),e.getStatus(),e.getEvidenceReferences(),e.getQualityMetadata(),e.getAiProvider(),e.getAiModel(),e.getAiOutcome(),e.getAiLatencyMs());}}}
